/**
 * Type re-exports + window global for the vendored TradingView Advanced Charts
 * library. The runtime bundle is served from `/charting_library/...` in
 * `public/`; this file teaches TypeScript about the same module shape so the
 * React wrapper and Datafeed adapter type-check.
 *
 * The big `charting_library.d.ts` file is generated by dts-bundle-generator and
 * already inlines every datafeed type, so we do NOT also vendor
 * `datafeed-api.d.ts` (it would cause duplicate-identifier errors).
 *
 * Types come straight from the runtime bundle's own declaration file in
 * `public/charting_library/` (audit M14: a second 30k-line copy used to live
 * next to this file and could silently diverge from the runtime library).
 * `public/charting_library` is excluded from the tsconfig root set, but
 * explicit type imports like these are still followed and checked.
 */

import type {
  ChartingLibraryWidgetConstructor,
} from "../../../public/charting_library/charting_library";

export type {
  ChartingLibraryWidgetConstructor,
  ChartingLibraryWidgetOptions,
  IChartingLibraryWidget,
  IChartWidgetApi,
  IDatafeedChartApi,
  IExternalDatafeed,
  LibrarySymbolInfo,
  Bar,
  Mark,
  TimescaleMark,
  ResolutionString,
  PeriodParams,
  HistoryCallback,
  DatafeedErrorCallback,
  SearchSymbolsCallback,
  ResolveCallback,
  GetMarksCallback,
  SubscribeBarsCallback,
  OnReadyCallback,
  DatafeedConfiguration,
  SearchSymbolResultItem,
  ThemeName,
  EntityId,
} from "../../../public/charting_library/charting_library";

declare global {
  interface Window {
    /**
     * Populated when the `/charting_library/charting_library.standalone.js`
     * script tag has loaded. Use the React wrapper rather than reading this
     * directly so we get a stable lifecycle.
     */
    TradingView?: {
      widget: ChartingLibraryWidgetConstructor;
    };
  }
}
